template <typename T, typename Cleaner>
class RAII {
public:
    RAII(T resource, Cleaner cleaner) : resource_(resource), cleaner_(cleaner) {}
    ~RAII() { cleaner_(resource_); }
private:
    T resource_;
    Cleaner cleaner_;
};

template <typename T, typename... Args>
class Singleton {
public:
    static T& Instance(Args&&... args) {
        static T instance(std::forward<Args>(args)...);
        return instance;
    }
private:
    Singleton() = default;
};

template <typename T, typename... Args>
class SingletonPtr {
public:
    static std::shared_ptr<T> Instance(Args&&... args) {
        static auto instance = std::make_shared<T>(std::forward<Args>(args)...);
        return instance;
    }
private:
    SingletonPtr() = default;
};

class MappedReadOnlyFile {
public:
    MappedReadOnlyFile()
        : file_size_(0),
          file_data_(nullptr) {}

MappedReadOnlyFile(const MappedReadOnlyFile&) = delete;

MappedReadOnlyFile(MappedReadOnlyFile&& other)
    : file_size_(other.file_size_),
      file_data_(other.file_data_) {
        other.file_size_ = 0;
        other.file_data_ = nullptr;
    }

MappedReadOnlyFile& operator=(const MappedReadOnlyFile&) = delete;

MappedReadOnlyFile& operator=(MappedReadOnlyFile&& other) {
    if (this != &other) {
        file_size_ = other.file_size_;
        file_data_ = other.file_data_;
        other.file_size_ = 0;
        other.file_data_ = nullptr;
    }
    return *this;
}

~MappedReadOnlyFile() {
    Unmap();
}

void Map(std::string path) {
